using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Spacetime;

internal sealed class NativeTimeProfileDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/ConceptDynamics/Spacetime/NativeTimeProfile.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Native time profiles, copy polynomials, and exact copy expressibility of tail regions.",
        H("Native Time Profiles"),
        Blocks(
            Describe.Lean(DescribeId.Create("successors"), DeclarationHandle.Create(Prefix + "successors"),
                H("Reflexive current successors"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The finite set retains complete timed attributes of the current event itself and all its current causal successors, including unselected targets."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("cell"), DeclarationHandle.Create(Prefix + "cell"),
                H("Native event cell"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A current event determines its timed attribute, selected Boolean bit, and finite successor attribute set."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gamma"), DeclarationHandle.Create(Prefix + "gamma"),
                H("Signed finite time profile"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Sum signed singleton cell measures over every current event. Noncurrent archive events contribute no cells. Events in the same cell add their integer coefficients."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("push"), DeclarationHandle.Create(Prefix + "push"),
                H("Linear cell transport"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Transport a finitely supported integer profile along a cell map, adding coefficients when cells merge."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("readout"), DeclarationHandle.Create(Prefix + "readout"),
                H("Terminal selected charge"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("This integer linear functional weights selected cells by one and unselected cells by zero."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("readout-gamma"), DeclarationHandle.Create(Prefix + "readout_gamma"),
                H("Terminal readout equals native charge"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every rich native history, applying the selected-cell functional to its complete time profile gives precisely its native q readout."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("shift-attribute"), DeclarationHandle.Create(Prefix + "shiftAttribute"),
                H("Integer attribute shift"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Add an arbitrary integer to time while preserving position, sign and source."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("unary-cell"), DeclarationHandle.Create(Prefix + "unaryCell"),
                H("All five unary updates"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Complement flips selection. Spatial and source filters conjoin their predicate with selection. Causal filtering tests whether the successor set hits the fixed timed-attribute predicate. Shifting changes both the own attribute and every successor attribute."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gamma-unary"), DeclarationHandle.Create(Prefix + "gamma_unary"),
                H("Native unary operations are linear pushes"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every balanced history and every native unary primitive, the actual output time profile equals the corresponding linear push of the input profile."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("gamma-parallel"), DeclarationHandle.Create(Prefix + "gamma_parallel"),
                H("Parallel profiles add"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every pair of balanced histories, the complete profile of their tagged parallel composite is the sum of the two profiles. Actual current events are reindexed; each component retains its successor set."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("product-attribute"), DeclarationHandle.Create(Prefix + "productAttribute"),
                H("Generated product attribute"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Generated time is the maximum parent time plus one. Positions add, signs multiply via Boolean equality, and sources form the ordered tree product."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("product-cell"), DeclarationHandle.Create(Prefix + "productCell"),
                H("Generated product cell"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Parent selection bits conjoin. The successor set of a newly generated current event is the singleton containing its own generated attribute."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("product-push"), DeclarationHandle.Create(Prefix + "productPush"),
                H("Bilinear cell push"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Extend the generated cell operation by integer bilinearity in the two finitely supported profiles."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("gamma-product"), DeclarationHandle.Create(Prefix + "gamma_product"),
                H("Native product equals the bilinear push"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every pair of balanced histories, the actual generated-product profile equals the bilinear push of the two parent profiles. The proof uses the exact parent-pair current equivalence and absence of paths out of generated nodes."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("pack"), DeclarationHandle.Create(Prefix + "pack"),
                H("Homogenized native profile"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A balanced native history is embedded as the pair consisting of the integer one and its complete time profile. The extra coordinate represents constants in the multilinear syntax interpretation."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("model"), DeclarationHandle.Create(Prefix + "model"),
                H("Multilinear interpretation of the copy syntax"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Each input occurrence occupies a distinct multilinear coordinate. Constants use the empty coordinate family. Unary nodes use linear profile pushes. Binary nodes combine disjoint leaf families using bilinear homogenized parallel or product maps. Temporal nodes are assigned parallel semantics here; the correctness theorem explicitly requires temporal freedom."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("model-eval"), DeclarationHandle.Create(Prefix + "model_eval"),
                H("The multilinear model computes native evaluation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every arity, temporal-free copy term, independent balanced leaf assignment and successful native result, applying the multilinear model to the packed leaves gives exactly the packed result. Structural induction consumes the native unary, parallel and product profile updates. This connects the formal multilinear interpretation to the actual finite native histories."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("copies"), DeclarationHandle.Create(Prefix + "copies"),
                H("Tagged parallel copies"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("copies 0 is the empty balanced history and copies (n+1) appends one tagged parallel copy of the input."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("value"), DeclarationHandle.Create(Prefix + "value"),
                H("Independent copy evaluation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("value is the total native value of a copy term under an independent leaf assignment, with the empty history as the failure default."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("polynomial-law"), DeclarationHandle.Create(Prefix + "CopyPolynomialLaw"),
                H("The 5B/5C polynomial bridge"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every positive temporal-free copy term and balanced input, diagonal evaluation on independently replicated leaves is an integer polynomial in the replication count. Its degree is bounded by the number of input occurrences, its constant coefficient is q(N(0)), and its linear coefficient is the sum of one-hole slice values minus the full constant correction r·q(N(0)). The theorem copy_polynomial_law proves this statement from the actual native time profile."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("profile-coefficients"), DeclarationHandle.Create(Prefix + "profileCoefficients"),
                H("Squarefree profile coefficients"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A coefficient is the multilinear profile model evaluated with the input profile on the indicated set of leaf occurrences and the empty profile elsewhere."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("profile-multiaffine"), DeclarationHandle.Create(Prefix + "profile_multiaffine"),
                H("Native independent-copy expansion"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every temporal-free copy term, balanced input and independently chosen natural replication counts, the actual native profile is the sum over sets of distinct leaf occurrences, weighted by the product of their counts. The proof consumes model_eval and the primitive profile updates."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("proved-polynomial"), DeclarationHandle.Create(Prefix + "copy_polynomial_law"),
                H("Lemma 5B and the full 5C coefficient"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The actual charge of a temporal-free term on m copies at every leaf is an integer polynomial of degree at most the arity. The constant coefficient is q(N(0)); the linear coefficient is the sum of the one-leaf slice charges minus r times q(N(0)). No vanishing constant is assumed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("region-linear"), DeclarationHandle.Create(Prefix + "CopiesRegionLinear"),
                H("Region readout under copies"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("This predicate specifies integer linearity of every region readout under tagged parallel copies; copies_region_linear proves it."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("word-readout"), DeclarationHandle.Create(Prefix + "wordReadout"),
                H("Scalar readout of a native word"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("wordReadout extracts q from a successful native one-hole word and returns the neutral integer on failure."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("slice-law"), DeclarationHandle.Create(Prefix + "CopySliceReadoutLaw"),
                H("Finite one-hole slice family"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("CopySliceReadoutLaw is the exact finite normalization consequence needed after the polynomial bridge: every total copy expression representing the fixed region supplies a finite family of total one-hole words whose readouts sum to that region."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("saturation-law"), DeclarationHandle.Create(Prefix + "CopySaturationLaw"),
                H("Joint saturation for finite word families"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("CopySaturationLaw records the common indistinguishability construction below a nonpositive time threshold for any finite family of total one-hole words."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("copy-expressible"), DeclarationHandle.Create(Prefix + "CopyQExpressible"),
                H("Positive finite diagonal copy expression"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("A region is copy-expressible when some positive finite copy term is total on every balanced input and its diagonal q readout equals the region readout."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("polynomial-identification"), DeclarationHandle.Create(Prefix + "polynomial_identification"),
                H("Identification from natural evaluations"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("An integer polynomial whose values at all natural numbers are n times a fixed integer is X multiplied by the constant polynomial a."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("proved-region-linearity"), DeclarationHandle.Create(Prefix + "copies_region_linear"),
                H("Exact regional replication law"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every fixed region readout on n tagged parallel copies equals n times its value on the original balanced input."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("proved-saturation"), DeclarationHandle.Create(Prefix + "copy_saturation_law"),
                H("Common finite-family saturation"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Any finite family of total one-hole words admits a common nonpositive threshold and, at every position and every pair of times below it, a pair of inputs with equal readouts for every word. The proof reuses the existing finite predicate construction and its saturation theorem. The selected positive event has a common source in the pair; this statement does not require that source to be leaf(0)."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("proved-slice"), DeclarationHandle.Create(Prefix + "copy_slice_readout_law"),
                H("Polynomial identification recovers the slices"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Normalize the total copy term before choosing the input. Identify its polynomial from all natural replication counts using regional linearity, obtain zero constant coefficient, and use the full linear coefficient to recover the exact sum of the fixed one-hole slices."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("sum-to-tail"), DeclarationHandle.Create(Prefix + "sum_word_readouts_implies_tail"),
                H("Finite word sums force a uniform tail"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The proved joint saturation shows that a finite sum of total one-hole word readouts cannot distinguish sufficiently early times at one position; equality of the sum and the selected-region calculation therefore forces Tail."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("copy-to-tail"), DeclarationHandle.Create(Prefix + "copy_q_expressible_implies_tail"),
                H("Copy necessity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Copy expressibility implies Tail by the proved polynomial, slice-readout and finite joint-saturation results, without additional law assumptions."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("tail-to-copy"), DeclarationHandle.Create(Prefix + "tail_implies_copy_q_expressible"),
                H("Tail supplies a one-copy expression"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The existing one-hole tail construction embeds as a positive one-occurrence copy term."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("two-way"), DeclarationHandle.Create(Prefix + "proposition64"),
                H("Proposition 64"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every region, the exact positive-arity all-input copy criterion is equivalent to Tail. Necessity uses the native profile polynomial, its full linear coefficient, and finite joint saturation; sufficiency reuses the frozen one-hole construction. No profile or saturation assumptions remain."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("three-way-theorem"), DeclarationHandle.Create(Prefix + "proposition64_three_way"),
                H("Three-way equivalence"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every region, copy expressibility is equivalent to the conjunction of the existing one-hole QExpressible criterion and Tail. The copy necessity retains the native polynomial proof on its live dependency path."))), DescribeRole.Theorem)
        ),
        [
            DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/ConceptDynamics/Spacetime/CoarseObservation")),
            DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/ConceptDynamics/Spacetime/TotalCopyNormalization")),
            DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/ConceptDynamics/Spacetime/RegionFilterQExpressibility"))
        ]));
}
